css:
[data-bz-node="loc-features-band"]{padding-top:90px;padding-bottom:90px;}
[data-bz-node="loc-features-band"] .bz-block{padding-block:0;}
.bz-block[data-bz-node="loc-features-heading"] p.bz-eyebrow{font:700 11px/1 var(--font-body);letter-spacing:.16em;color:var(--muted);margin:0 0 18px;}
[data-bz-node="loc-features-heading"] h2{font:800 34px/1.7 var(--font-heading);letter-spacing:normal;margin:0 0 40px;}
[data-bz-node="loc-features-grid-row"]{gap:24px;}
[data-bz-node="loc-features-grid-row"] > .bz-col{display:flex;flex-direction:column;background:var(--card);border:1px solid var(--line);padding:28px;}
[data-bz-node="loc-features-grid-row"] .bz-headingblock,
[data-bz-node="loc-features-grid-row"] .bz-text{max-width:none;}
[data-bz-node="loc-features-grid-row"] h3{font:800 18px/1.7 var(--font-heading);margin:0 0 12px;}
[data-bz-node="loc-features-grid-row"] .bz-block--text{margin-bottom:14px;}
[data-bz-node="loc-features-grid-row"] .bz-block--text p{font-size:14px;line-height:1.7;color:#3f3f3f;margin:0;}
[data-bz-node="loc-features-grid-row"] .bz-block--buttons{margin-top:auto;}
[data-bz-node="loc-features-grid-row"] .bz-btn{padding:0;font:700 15px/1.7 var(--font-body);text-decoration:none;}
@media (max-width:640px){[data-bz-node="loc-features-band"]{padding-top:56px;padding-bottom:56px;}}
